const raw = $input.first().json;
const input = raw.body ?? raw; // handle both webhook (wrapped) and Execute-Workflow (direct) triggers

return [
  {
    json: {
      repository: input.repository,

      run_id: input.workflow_run?.run_id,
      run_number: input.workflow_run?.run_number,
      head_sha: input.workflow_run?.head_sha,
      branch: input.workflow_run?.branch,
      conclusion: input.workflow_run?.conclusion,
      workflow_name: input.workflow_run?.workflow_name,
      html_url: input.workflow_run?.html_url,

      junit_xml: input.test_results?.junit_xml ?? null,
      coverage_xml: input.test_results?.coverage_xml ?? null,

      junit_available: input.evidence?.junit_available ?? false,
      coverage_available: input.evidence?.coverage_available ?? false
    }
  }
];

const input = $input.first().json;

const junit = input.junit_xml || '';
const coverage = input.coverage_xml || '';

const testsMatch = junit.match(/tests="(\d+)"/);
const failuresMatch = junit.match(/failures="(\d+)"/);
const errorsMatch = junit.match(/errors="(\d+)"/);
const skippedMatch = junit.match(/skipped="(\d+)"/);

const lineRateMatch = coverage.match(/line-rate="([^"]+)"/);

// Real bug, found by testing against a live multi-testcase run: the old
// regex used [\s\S]*? to span from one <testcase ...> tag to the NEXT
// <failure>, which happily skips across self-closing sibling testcases and
// pairs the WRONG classname/name with a failure that belongs to a later
// test. Fixed with explicit per-testcase boundary scanning (self-closing
// "/>" or the matching "</testcase>"), same technique proven in the
// get_test_history tool.
const failedTests = [];
let searchFrom = 0;
while (true) {
  const startIdx = junit.indexOf('<testcase', searchFrom);
  if (startIdx === -1) break;
  const tagCloseIdx = junit.indexOf('>', startIdx);
  if (tagCloseIdx === -1) break;
  const openTag = junit.slice(startIdx, tagCloseIdx + 1);
  const isSelfClosing = openTag.endsWith('/>');
  let blockEnd;
  if (isSelfClosing) {
    blockEnd = tagCloseIdx + 1;
  } else {
    const closeIdx = junit.indexOf('</testcase>', tagCloseIdx);
    blockEnd = closeIdx !== -1 ? closeIdx + '</testcase>'.length : junit.length;
  }
  const block = junit.slice(startIdx, blockEnd);
  if (block.includes('<failure') || block.includes('<error')) {
    const classnameMatch = openTag.match(/classname="([^"]*)"/);
    const nameMatch = openTag.match(/\sname="([^"]*)"/);
    const msgMatch = block.match(/<(?:failure|error)[^>]*message="([^"]*)"/);
    failedTests.push({
      classname: classnameMatch ? classnameMatch[1] : '',
      name: nameMatch ? nameMatch[1] : '',
      message: msgMatch ? msgMatch[1] : ''
    });
  }
  searchFrom = blockEnd;
}

return [
  {
    json: {
      repository: input.repository,
      run_id: input.run_id,
      run_number: input.run_number,
      head_sha: input.head_sha,
      branch: input.branch,
      conclusion: input.conclusion,
      workflow_name: input.workflow_name,
      html_url: input.html_url,

      test_summary: {
        total: Number(testsMatch?.[1] || 0),
        failures: Number(failuresMatch?.[1] || 0),
        errors: Number(errorsMatch?.[1] || 0),
        skipped: Number(skippedMatch?.[1] || 0),
        passed: Math.max(
          0,
          Number(testsMatch?.[1] || 0) -
          Number(failuresMatch?.[1] || 0) -
          Number(errorsMatch?.[1] || 0) -
          Number(skippedMatch?.[1] || 0)
        )
      },

      coverage: {
        line_rate: Number(lineRateMatch?.[1] || 0),
        percentage: Number(lineRateMatch?.[1] || 0) * 100
      },

      failed_tests: failedTests
    }
  }
];

const items = $input.all();

const raw = items[0]?.json;
const isErrorResponse = raw && typeof raw === 'object' && !Array.isArray(raw) && (raw.message || raw.status) && !Array.isArray(raw.alerts);

if (isErrorResponse) {
  return [{ json: { source: 'dependabot', available: false, count: 0, alerts: [], known_tracked: [], tracked_skipped_count: 0, error: raw.message || 'unavailable' } }];
}

const allAlerts = items.flatMap((item) => {
  const data = item.json;
  if (Array.isArray(data)) return data;
  if (Array.isArray(data.alerts)) return data.alerts;
  return data ? [data] : [];
});

const mapped = allAlerts.map((alert) => ({
  number: alert.number ?? null,
  state: alert.state ?? null,
  dependency: alert.dependency?.package?.name ?? null,
  ecosystem: alert.dependency?.package?.ecosystem ?? null,
  manifest_path: alert.dependency?.manifest_path ?? null,
  severity: alert.security_advisory?.severity ?? null,
  cve: alert.security_advisory?.cve?.id ?? null,
  ghsa: alert.security_advisory?.ghsa_id ?? null,
  summary: alert.security_advisory?.summary ?? null,
  vulnerable_version_range: alert.security_vulnerability?.vulnerable_version_range ?? null,
  first_patched_version: alert.security_vulnerability?.first_patched_version?.identifier ?? null,
}));

// --- PR SCOPE ATTRIBUTION (jury feedback) -------------------------------
// A release gate that blames a PR for the repo's pre-existing debt is a gate
// developers switch off. Every finding is labelled with whether THIS PR could
// have introduced it, decided from the PR's actual changed-file list -- not
// from the model's opinion.
//
// Fails OPEN: if scope cannot be determined, findings are marked 'unknown' and
// still reported. We would rather over-report than silently hide a real issue.
let scope = { available: false, reason_unavailable: 'scope lookup did not run' };
try {
  scope = $('Ensure PR Scope').first().json.pr_scope || scope;
} catch (e) {
  scope = { available: false, reason_unavailable: 'scope lookup did not run' };
}
const changedFiles = scope.changed_files || [];

// A dependency vulnerability enters the repo through a manifest. If this PR
// does not modify the manifest that declares the package, the PR cannot have
// introduced the vulnerable dependency -- that is a fact about the diff, not
// an inference.
//
// Deliberately narrow wording: "not introduced by this PR" is NOT the same as
// "this PR is unaffected". A PR can add code that newly *reaches* an
// already-vulnerable package. Reachability stays the agent's job; this field
// only answers who introduced the dependency.
function attribute(a) {
  if (!scope.available) {
    return { attribution: 'unknown', attribution_reason: `PR scope unavailable (${scope.reason_unavailable}) -- reported without scoping.` };
  }
  if (a.manifest_path && changedFiles.includes(a.manifest_path)) {
    return { attribution: 'pr_touched_manifest', attribution_reason: `This PR modifies ${a.manifest_path}, the manifest that declares this dependency.` };
  }
  return {
    attribution: 'pre_existing',
    attribution_reason: `This PR does not modify ${a.manifest_path || 'any dependency manifest'}, so it did not introduce this dependency.`,
  };
}

// DEDUP (jury feedback): never spend tool calls re-investigating a finding
// we have already filed as a tracked GitHub issue.
let trackedList = [];
try {
  trackedList = $('Ensure Tracked Issues').first().json.tracked || [];
} catch (e) {
  trackedList = [];
}
const byGhsa = {};
for (const t of trackedList) {
  if (t.ghsa) byGhsa[String(t.ghsa).toUpperCase()] = t;
}
const isTracked = (a) => a.ghsa && byGhsa[String(a.ghsa).toUpperCase()];

// GitHub opens a separate alert per manifest, so one advisory can appear
// several times (this repo: 9 alerts across 6 distinct advisories). Count the
// alerts honestly, but list each advisory once -- a reader does not need the
// same GHSA three times.
const knownTrackedAll = mapped.filter(isTracked).map((a) => {
  const t = byGhsa[String(a.ghsa).toUpperCase()];
  return { dependency: a.dependency, ghsa: a.ghsa, severity: a.severity, tracked_issue: t.number, tracked_issue_url: t.url, ...attribute(a) };
});
const seenGhsa = new Set();
const knownTracked = knownTrackedAll.filter((k) => {
  const key = String(k.ghsa).toUpperCase();
  if (seenGhsa.has(key)) return false;
  seenGhsa.add(key);
  return true;
});
const untracked = mapped.filter((a) => !isTracked(a)).map((a) => ({ ...a, ...attribute(a) }));

// Cap the payload sent to the LLM. Ordering now puts anything this PR could
// have introduced ahead of pre-existing debt, so the limited investigation
// budget is spent on what this PR is actually accountable for.
const SEVERITY_RANK = { critical: 0, high: 1, medium: 2, moderate: 2, low: 3 };
const ATTR_RANK = { pr_touched_manifest: 0, unknown: 1, pre_existing: 2 };
const sorted = [...untracked].sort((a, b) => {
  const at = (ATTR_RANK[a.attribution] ?? 1) - (ATTR_RANK[b.attribution] ?? 1);
  if (at !== 0) return at;
  return (SEVERITY_RANK[a.severity] ?? 9) - (SEVERITY_RANK[b.severity] ?? 9);
});
const MAX_ALERTS = 3;
const shown = sorted.slice(0, MAX_ALERTS);
const omittedCount = Math.max(0, sorted.length - shown.length);

const introducedCount = untracked.filter((a) => a.attribution === 'pr_touched_manifest').length;

return [
  {
    json: {
      source: 'dependabot',
      available: true,
      count: mapped.length,
      new_count: untracked.length,
      shown_count: shown.length,
      omitted_count: omittedCount,
      omitted_note: omittedCount > 0 ? `${omittedCount} untracked alert(s) not shown to the agent; ordered by PR-attribution then severity` : null,
      tracked_skipped_count: knownTrackedAll.length,
      tracked_advisory_count: knownTracked.length,
      tracked_skipped_note: knownTrackedAll.length > 0 ? `${knownTrackedAll.length} alert(s) across ${knownTracked.length} advisories skipped -- already filed as tracked GitHub issues, not re-investigated` : null,
      known_tracked: knownTracked,
      scope_available: scope.available,
      introduced_by_pr_count: introducedCount,
      pre_existing_count: untracked.filter((a) => a.attribution === 'pre_existing').length,
      alerts: shown,
    },
  },
];

const items = $input.all();
const raw = items[0]?.json;
const isErrorResponse = raw && typeof raw === 'object' && !Array.isArray(raw) && (raw.message || raw.status) && !Array.isArray(raw.alerts);
if (isErrorResponse) {
  return [{ json: { source: 'code_scanning', available: false, count: 0, alerts: [], error: raw.message || 'unavailable' } }];
}
const alerts = items.flatMap(item => {
  const data = item.json;
  if (Array.isArray(data)) return data;
  if (Array.isArray(data.alerts)) return data.alerts;
  return data ? [data] : [];
});
const mapped = alerts.map(alert => ({
  number: alert.number ?? null, state: alert.state ?? null, rule_id: alert.rule?.id ?? null,
  rule_description: alert.rule?.description ?? null, severity: alert.rule?.security_severity_level ?? null,
  tool: alert.tool?.name ?? null, category: alert.rule?.security_category ?? null, html_url: alert.html_url ?? null,
  // path is what makes scope attribution possible -- a code-scanning alert
  // points at a specific file, so "did this PR touch that file" is decidable.
  path: alert.most_recent_instance?.location?.path ?? null,
  start_line: alert.most_recent_instance?.location?.start_line ?? null,
  created_at: alert.created_at ?? null, updated_at: alert.updated_at ?? null
}));

// --- PR SCOPE ATTRIBUTION (jury feedback) -------------------------------
// A release gate that blames a PR for the repo's pre-existing debt is a gate
// developers switch off. Every finding is labelled with whether THIS PR could
// have introduced it, decided from the PR's actual changed-file list -- not
// from the model's opinion.
//
// Fails OPEN: if scope cannot be determined, findings are marked 'unknown' and
// still reported. We would rather over-report than silently hide a real issue.
let scope = { available: false, reason_unavailable: 'scope lookup did not run' };
try {
  scope = $('Ensure PR Scope').first().json.pr_scope || scope;
} catch (e) {
  scope = { available: false, reason_unavailable: 'scope lookup did not run' };
}
const changedFiles = scope.changed_files || [];

function attribute(a) {
  if (!scope.available) {
    return { attribution: 'unknown', attribution_reason: `PR scope unavailable (${scope.reason_unavailable}) -- reported without scoping.` };
  }
  if (a.path && changedFiles.includes(a.path)) {
    return { attribution: 'introduced_by_pr', attribution_reason: `This PR modifies ${a.path}, the file this alert points at.` };
  }
  return { attribution: 'pre_existing', attribution_reason: `This PR does not modify ${a.path || 'the flagged file'}, so this alert predates it.` };
}

const attributed = mapped.map((a) => ({ ...a, ...attribute(a) }));

const SEVERITY_RANK = { critical: 0, high: 1, medium: 2, moderate: 2, low: 3 };
const ATTR_RANK = { introduced_by_pr: 0, unknown: 1, pre_existing: 2 };
const sorted = [...attributed].sort((a, b) => {
  const at = (ATTR_RANK[a.attribution] ?? 1) - (ATTR_RANK[b.attribution] ?? 1);
  if (at !== 0) return at;
  return (SEVERITY_RANK[a.severity] ?? 9) - (SEVERITY_RANK[b.severity] ?? 9);
});
const MAX_ALERTS = 3;
const shown = sorted.slice(0, MAX_ALERTS);
const omittedCount = Math.max(0, sorted.length - shown.length);

return [{ json: {
  source: 'code_scanning',
  available: true,
  count: mapped.length,
  shown_count: shown.length,
  omitted_count: omittedCount,
  omitted_note: omittedCount > 0 ? `${omittedCount} alert(s) not shown to the agent; ordered by PR-attribution then severity` : null,
  scope_available: scope.available,
  introduced_by_pr_count: attributed.filter(a => a.attribution === 'introduced_by_pr').length,
  pre_existing_count: attributed.filter(a => a.attribution === 'pre_existing').length,
  alerts: shown,
} }];

const items = $input.all();

// PR scope travels with the evidence so the agent is TOLD what this PR changed
// rather than inferring it. Read defensively: if the scope branch failed, the
// agent still runs, just unscoped.
let prScope;
try {
  prScope = $('Ensure PR Scope').first().json.pr_scope;
} catch (e) {
  prScope = null;
}
if (!prScope) prScope = { available: false, reason_unavailable: 'scope lookup did not run' };

// Behavioural comparison of real responses across the PR. Read defensively:
// if the chain did not run, the agent still runs, just without it.
let semantic;
try {
  semantic = $('Diff Responses').first().json.semantic;
} catch (e) {
  semantic = null;
}
if (!semantic) semantic = { available: false, divergences: [], divergence_count: 0, reason: 'the behavioural comparison did not run' };

const test = items.find(i => i.json.test_summary);
const dependabot = items.find(i => i.json.source === 'dependabot');
const codeScanning = items.find(i => i.json.source === 'code_scanning');

return [
  {
    json: {
      repository: test?.json.repository ?? '',
      pr_scope: prScope,
      semantic: semantic,
      run_id: test?.json.run_id ?? '',
      run_number: test?.json.run_number ?? null,
      head_sha: test?.json.head_sha ?? '',
      branch: test?.json.branch ?? '',
      conclusion: test?.json.conclusion ?? '',
      workflow_name: test?.json.workflow_name ?? '',
      html_url: test?.json.html_url ?? '',

      test_summary: test?.json.test_summary ?? {
        total: 0,
        passed: 0,
        failures: 0,
        errors: 0,
        skipped: 0
      },

      coverage: test?.json.coverage ?? {
        line_rate: 0,
        percentage: 0
      },

      failed_tests: test?.json.failed_tests ?? [],

      dependabot: dependabot?.json ?? {
        source: 'dependabot',
        available: false,
        count: 0,
        alerts: []
      },

      code_scanning: codeScanning?.json ?? {
        source: 'code_scanning',
        available: false,
        count: 0,
        alerts: []
      }
    }
  }
];

const raw = $input.first().json;
const agentText = raw.output || '';
// Set when the agent node itself failed (its On Error setting passes the error on).
const agentError = raw.error ? String(raw.error) : null;

// LLM responses arrive in more shapes than "just the JSON object", and one
// strict JSON.parse turns a perfectly good analysis into a 0%-confidence
// fail-safe comment. Observed live (execution 523): GLM emitted a prose
// preamble AND its response was truncated mid-object, so the closing fence
// never arrived, the fence regex matched nothing, and JSON.parse was handed
// the prose. The analysis itself was correct and was thrown away.
//
// Strategies are tried most-trustworthy first, and which one succeeded is
// reported downstream -- a recovered response is never passed off as a clean one.
function tryParse(t) {
  try { return JSON.parse(t); } catch (e) { return null; }
}

// Walks to the matching close brace, respecting strings and escapes, so a
// brace inside a summary string cannot terminate the object early.
function extractBalanced(text) {
  const start = text.indexOf('{');
  if (start < 0) return null;
  let depth = 0, inStr = false, esc = false;
  for (let i = start; i < text.length; i++) {
    const ch = text[i];
    if (esc) { esc = false; continue; }
    if (ch === '\\') { esc = true; continue; }
    if (ch === '"') { inStr = !inStr; continue; }
    if (inStr) continue;
    if (ch === '{') depth++;
    else if (ch === '}') { depth--; if (depth === 0) return { frag: text.slice(start, i + 1), complete: true }; }
  }
  return { frag: text.slice(start), complete: false };
}

// Truncated object: cut back to the last point that parses once the still-open
// brackets are closed. Lossy by construction -- callers must label it.
function repairTruncated(frag) {
  const closeAt = (cut) => {
    let inStr = false, esc = false;
    const stack = [];
    for (let i = 0; i <= cut; i++) {
      const ch = frag[i];
      if (esc) { esc = false; continue; }
      if (ch === '\\') { esc = true; continue; }
      if (ch === '"') { inStr = !inStr; continue; }
      if (inStr) continue;
      if (ch === '{') stack.push('}');
      else if (ch === '[') stack.push(']');
      else if (ch === '}' || ch === ']') stack.pop();
    }
    if (inStr) return null;
    let out = frag.slice(0, cut + 1).replace(/,\s*$/, '');
    while (stack.length) out += stack.pop();
    return out;
  };

  let attempts = 0;
  for (let i = frag.length - 1; i >= 0 && attempts < 800; i--) {
    const ch = frag[i];
    if (ch !== '"' && ch !== '}' && ch !== ']' && !/[0-9a-zA-Z]/.test(ch)) continue;
    attempts++;
    const candidate = closeAt(i);
    if (!candidate) continue;
    const parsed = tryParse(candidate);
    if (parsed && typeof parsed === 'object' && parsed.decision) return parsed;
  }
  return null;
}

let parsed = null;
let parseError = null;
let strategy = null;

// 1. clean JSON
parsed = tryParse(agentText.trim());
if (parsed) strategy = 'direct';

// 2. properly closed markdown fence
if (!parsed) {
  const m = agentText.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (m) { parsed = tryParse(m[1].trim()); if (parsed) strategy = 'fenced'; }
}

// 3. opening fence with no closing fence (truncated response)
if (!parsed) {
  const m = agentText.match(/```(?:json)?\s*([\s\S]*)$/);
  if (m) { parsed = tryParse(m[1].trim()); if (parsed) strategy = 'unclosed_fence'; }
}

// 4. JSON object embedded anywhere in prose
let balanced = null;
if (!parsed) {
  balanced = extractBalanced(agentText);
  if (balanced) { parsed = tryParse(balanced.frag); if (parsed) strategy = 'embedded_object'; }
}

// 5. last resort: repair a truncated object
if (!parsed && balanced && !balanced.complete) {
  parsed = repairTruncated(balanced.frag);
  if (parsed) strategy = 'repaired_truncated';
}

if (!parsed) {
  parseError = agentError
    ? 'the agent failed before answering: ' + agentError
    : 'no parseable JSON object found in agent output (length ' + agentText.length + ')';
}

// Pull the deterministic evidence context back in -- the validation gate checks
// the agent's claims against this, not against the agent's own say-so.
const context = $('Build Validation Context').first().json;

return [{
  json: {
    agent_raw_output: agentText,
    agent_parsed: parsed,
    agent_parse_error: parseError,
    agent_parse_strategy: strategy,
    agent_attempt: $runIndex + 1,
    agent_output_truncated: !!(balanced && !balanced.complete),
    context: context
  }
}];

// Deterministic Validation Gate -- the PRD's core trust mechanism: the LLM
// classifies (decision/confidence/reasoning), this code enforces policy. The
// agent's own "approve" is NEVER taken at face value here -- every approve is
// checked against the deterministic evidence, and every gate below can escalate
// the decision but the agent can never talk its way past one.
const input = $input.first().json;
const agent = input.agent_parsed;
const context = input.context;

const overrides = [];
let finalDecision;
let finalConfidence;

if (!agent || typeof agent !== 'object') {
  finalDecision = 'review';
  finalConfidence = 0;
  overrides.push('Agent output could not be parsed as valid JSON (parse error: ' + (input.agent_parse_error || 'unknown') + ') -- forced to review.');
} else {
  const validDecisions = ['approve', 'block', 'review'];
  let decision = validDecisions.includes(agent.decision) ? agent.decision : 'review';
  if (!validDecisions.includes(agent.decision)) {
    overrides.push('Agent returned an invalid decision value "' + agent.decision + '" -- forced to review.');
  }
  finalConfidence = typeof agent.confidence === 'number' ? agent.confidence : 0;

  // A recovered response is never presented as a clean one.
  if ((input.agent_attempt || 1) > 1) {
    overrides.push('Note: the agent\'s first response contained no verdict; it was asked once more and this verdict is from attempt ' + input.agent_attempt + '.');
  }
  if (input.agent_parse_strategy && !['direct', 'fenced'].includes(input.agent_parse_strategy)) {
    overrides.push('Note: the agent response was not clean JSON (recovered via: ' + input.agent_parse_strategy + ')' +
      (input.agent_output_truncated ? ' and was truncated mid-object, so findings below may be incomplete' : '') + '.');
  }

  // RULE 1: a real failing test (from deterministic XML parsing, not the agent's
  // claim) can never be silently approved.
  const failedTestCount = context?.test_summary?.failures ?? 0;
  if (failedTestCount > 0 && decision === 'approve') {
    decision = 'review';
    // A failure that is independently proven flaky AND pre-existing is still a
    // red CI run a human should sign off on -- but saying "agent said approve"
    // misrepresents why. State the real reason.
    const fv = input.flaky_verification || [];
    const allFlakyPreExisting = fv.length > 0 && fv.every((v) => v.deterministic_class === 'flaky' && v.attribution === 'pre_existing');
    if (allFlakyPreExisting) {
      overrides.push('Deterministic check: ' + failedTestCount + ' test failure(s) in this run, independently re-verified as flaky AND pre-existing -- not attributed to this PR. A red CI run still requires human sign-off, so approve is raised to review.');
    } else {
      overrides.push('Deterministic check: ' + failedTestCount + ' test failure(s) recorded in test_summary, but agent said approve -- overridden to review.');
    }
  }

  // RULE 2: can't approve if security evidence was unavailable (permissions
  // error, API failure). Approving without having actually checked is not
  // allowed -- matches PRD: insufficient evidence forces manual review.
  const securityUnavailable = (context?.dependabot?.available === false) || (context?.code_scanning?.available === false);
  if (securityUnavailable && decision === 'approve') {
    decision = 'review';
    overrides.push('Deterministic check: security evidence (Dependabot and/or Code Scanning) was unavailable, but agent said approve -- overridden to review.');
  }

  // RULE 3: low agent confidence forces human review even on an approve.
  if (finalConfidence < 70 && decision === 'approve') {
    decision = 'review';
    overrides.push('Deterministic check: agent confidence ' + finalConfidence + ' is below the 70 threshold for an approve decision -- overridden to review.');
  }

  // RULE 4: HARD GATE -- a detected secret always blocks. This is a gate, not
  // a score deduction: the agent cannot reason its way past it.
  const codeScanningAlerts = context?.code_scanning?.alerts || [];
  const hasSecretAlert = codeScanningAlerts.some((a) => {
    const tool = (a.tool || '').toLowerCase();
    const rule = (a.rule_id || '').toLowerCase();
    return tool.includes('gitleaks') || rule.includes('secret') || rule.includes('api-key') || rule.includes('credential');
  });
  if (hasSecretAlert && decision !== 'block') {
    decision = 'block';
    overrides.push('HARD GATE: a secret-detection alert (gitleaks/credential pattern) is present -- decision forced to block regardless of agent output. This gate cannot be overridden.');
  }

    // RULE 5: independently-verified flaky/regression mismatch -- this never
  // trusts the agent's own classification at face value. A separate,
  // deterministic re-call of get_test_history (not the agent's tool call) is
  // cross-checked against what the agent claimed. The dangerous direction is
  // the agent calling a genuine regression "flaky" (a false negative that
  // could wave through a real bug); that always forces at least review.
  const flakyVerification = input.flaky_verification || [];
  const dangerousMismatches = flakyVerification.filter(
    (v) => v.agrees === false && v.agent_class_normalized === 'flaky' && v.deterministic_class === 'regression'
  );
  const otherMismatches = flakyVerification.filter(
    (v) => v.agrees === false && !(v.agent_class_normalized === 'flaky' && v.deterministic_class === 'regression')
  );
  if (dangerousMismatches.length > 0) {
    if (decision !== 'block') decision = 'review';
    overrides.push(
      'HARD CHECK: independent re-verification of ' +
        dangerousMismatches.map((m) => m.test_name).join(', ') +
        ' via a fresh get_test_history call shows NO prior failures on main (deterministic_class=regression), but the agent classified it as flaky (' +
        dangerousMismatches.map((m) => '"' + m.agent_claimed + '"').join('; ') +
        ') -- overridden to review regardless of agent decision.'
    );
  }
  if (otherMismatches.length > 0) {
    overrides.push(
      'Note: independent re-verification disagrees with the agent on ' +
        otherMismatches.map((m) => m.test_name + ' (agent: ' + m.agent_class_normalized + ', re-verified: ' + m.deterministic_class + ')').join('; ') +
        ' -- lower-severity mismatch, not forcing a decision change, but flagged for review.'
    );
  }

  // RULE 6: findings already filed as tracked issues are skipped by the
  // investigation to save tool calls (dedup), but they are still real, still
  // open, and still shipping in this release. Skipping the re-investigation
  // must never quietly become approving the vulnerability.
  const knownTracked = context?.dependabot?.known_tracked || [];
  const trackedSevere = knownTracked.filter((k) => ['critical', 'high'].includes(String(k.severity || '').toLowerCase()));
  if (trackedSevere.length > 0 && decision === 'approve') {
    decision = 'review';
    overrides.push(
      'Deterministic check: ' + trackedSevere.length + ' previously-tracked critical/high finding(s) are still open (' +
      trackedSevere.map((k) => '#' + k.tracked_issue).join(', ') +
      ') -- skipped this run for efficiency, but still unresolved, so an approve is overridden to review.'
    );
  }

  // RULE 8: semantic divergence. The probe compares the app's ACTUAL responses
  // on both sides of the PR, so this fires on changes no test asserted. A
  // coherence break means a returned value stopped matching the request that
  // produced it -- deterministic, and independent of anything the agent says.
  const sem = context?.semantic || {};
  const coherenceBreaks = sem.available ? (sem.coherence_break_count || 0) : 0;
  // Purely additive behaviour changes are excluded by the detector, so this
  // never counts a new endpoint as something this PR broke.
  const semanticRegressions = sem.available ? (sem.regression_candidate_count || 0) : 0;

  if (coherenceBreaks > 0 && decision === 'approve') {
    decision = 'review';
    overrides.push(
      'Deterministic check: ' + coherenceBreaks + ' response value(s) now contradict the request that produced them' +
      ', on a build where the test suite passed. The agent approved anyway -- raised to review.'
    );
  }

  // RULE 7: scope (jury feedback). A finding that pre-dates this PR must not
  // be charged to this PR. A gate that blocks a README edit over the repo's
  // existing dependency debt is a gate developers learn to ignore.
  //
  // Deliberately downgrades block -> review, never -> approve: the findings are
  // still real and still visible, they just are not this PR's fault. Only
  // applies when scope was actually determined; unknown scope changes nothing.
  const scope7 = context?.pr_scope || { available: false };
  const dep7 = context?.dependabot || {};
  const cs7 = context?.code_scanning || {};
  const introducedFindings = (dep7.introduced_by_pr_count || 0) + (cs7.introduced_by_pr_count || 0) + semanticRegressions;
  const introducedTests = (input.flaky_verification || []).filter((v) => v.attribution === 'possibly_introduced').length;

  if (scope7.available && introducedFindings === 0 && introducedTests === 0 && decision === 'block') {
    decision = 'review';
    overrides.push(
      'Deterministic check: this PR changes only ' + (scope7.changed_files || []).join(', ') +
      ' and introduced none of the findings above -- all of them pre-date it. Downgraded from block to review: ' +
      'the findings stay visible and tracked, but this PR is not blamed for them.'
    );
  }

  // RULE 9: HARD GATE -- a regression this PR introduced always blocks.
  // Same stance as the secret gate: not something the agent can talk down.
  // "Regression" here is the deterministic cross-check's verdict, not the
  // agent's: a fresh get_test_history call found this test passing on main
  // with NO prior failures, and the PR changes code. Requires at least
  // MIN_CLEAN_RUNS clean runs so one lucky pass on a brand-new test can't
  // masquerade as a stable baseline.
  const MIN_CLEAN_RUNS = 3;
  const provenRegressions = (input.flaky_verification || []).filter((v) =>
    v.deterministic_class === 'regression' &&
    v.attribution === 'possibly_introduced' &&
    ((v.deterministic_evidence && v.deterministic_evidence.pass_count) || 0) >= MIN_CLEAN_RUNS
  );
  // When the agent already blocked, say so anyway: the reader should know this
  // block would stand even if the agent had approved. That independence is the
  // point -- the agent can be wrong, it just cannot be wrong alone.
  if (provenRegressions.length > 0 && decision === 'block') {
    overrides.push(
      'Independently confirmed: ' + provenRegressions.map((v) => v.test_name + ' (' + v.deterministic_evidence.pass_count +
        ' clean runs on main, 0 prior failures)').join('; ') +
      ' now fail(s) on a PR that changes code. The regression hard gate is met on its own, so this block does not depend on the agent.'
    );
  }
  if (provenRegressions.length > 0 && decision !== 'block') {
    const before = decision;
    decision = 'block';
    overrides.push(
      'HARD GATE: ' + provenRegressions.map((v) => v.test_name + ' (' + v.deterministic_evidence.pass_count +
        ' clean runs on main, 0 prior failures)').join('; ') +
      ' now fail(s), and this PR changes code (' + ((context?.pr_scope?.code_files) || []).join(', ') +
      '). A test with a clean history that starts failing on this change is a regression, not flakiness -- ' +
      before + ' raised to block.'
    );
  }

  // RULE 10: HARD GATE -- a business rule from the BASE contract that held
  // before this change and is broken by it always blocks. The rule and its
  // checker come from the base commit (see ci.yml), so the PR cannot have
  // loosened them; the evaluation is arithmetic in CI, not a model judgement.
  // A changed value alone can be intended; a broken invariant cannot, unless
  // the contract itself is changed -- which is its own reviewable diff.
  const semInv = context?.semantic || {};
  const brokenRules = semInv.available
    ? (semInv.divergences || []).filter((d) => d.kind === 'invariant_violation')
    : [];
  const newRuleFailures = semInv.available
    ? (semInv.divergences || []).filter((d) => d.kind === 'invariant_violation_new')
    : [];
  if (brokenRules.length > 0) {
    const names = Array.from(new Set(brokenRules.map((d) => String(d.path).replace('(rule) ', '')))).join(', ');
    if (decision !== 'block') {
      const before = decision;
      decision = 'block';
      overrides.push('HARD GATE: ' + brokenRules.length + ' business-rule check(s) held on the base commit and fail on this change (' +
        names + '). ' + before + ' raised to block.');
    } else {
      overrides.push('Independently confirmed: ' + brokenRules.length + ' business-rule check(s) held on the base commit and fail on this change (' +
        names + '). The business-rule hard gate is met on its own, so this block does not depend on the agent.');
    }
  }
  if (newRuleFailures.length > 0 && decision === 'approve') {
    decision = 'review';
    overrides.push('Deterministic check: a new endpoint fails ' + newRuleFailures.length + ' of its business-rule checks on arrival -- raised to review.');
  }

  finalDecision = decision;
}

return [{
  json: {
    repository: context?.repository ?? null,
    run_id: context?.run_id ?? null,
    head_sha: context?.head_sha ?? null,
    html_url: context?.html_url ?? null,
    agent_decision: agent?.decision ?? null,
    agent_confidence: agent?.confidence ?? null,
    agent_summary: agent?.summary ?? null,
    agent_test_findings: agent?.test_findings ?? [],
    agent_security_findings: agent?.security_findings ?? [],
    agent_validated_findings: agent?.validated_findings ?? [],
    agent_required_actions: agent?.required_actions ?? [],
    final_decision: finalDecision,
    final_confidence: finalConfidence,
    deterministic_overrides: overrides,
    flaky_verification: input.flaky_verification || [],
    known_tracked: context?.dependabot?.known_tracked || [],
    pr_scope: context?.pr_scope || null,
    semantic: context?.semantic || null,
    scoped_alerts: [
      ...(context?.dependabot?.alerts || []),
      ...(context?.code_scanning?.alerts || []),
    ].map((a) => ({
      dependency: a.dependency || a.rule_id || a.path || null,
      ghsa: a.ghsa || a.cve || null,
      severity: a.severity || null,
      attribution: a.attribution || 'unknown',
      attribution_reason: a.attribution_reason || null,
    })),
    tracked_skipped_count: context?.dependabot?.tracked_skipped_count || 0,
    was_overridden: overrides.length > 0,
    evaluated_at: new Date().toISOString()
  }
}];

// Combine the deterministic verdict with confirmation that GitHub was updated.
const gate = $('Deterministic Validation Gate').first().json;
const statusResponse = $input.first().json;
const statusPosted = !(statusResponse && (statusResponse.message || statusResponse.status === '404' || statusResponse.status === '422'));

return [{
  json: Object.assign({}, gate, {
    github_status_posted: statusPosted,
    github_status_response: statusResponse
  })
}];

const items = $input.all();
const realItems = items.filter((i) => i.json && Object.keys(i.json).length > 0);
if (realItems.length === 1) {
  const only = realItems[0].json;
  const looksLikeError = only && typeof only === 'object' && !Array.isArray(only) && (only.message || only.status) && !Array.isArray(only.alerts);
  if (looksLikeError) return [{ json: only }];
}
return [{ json: { alerts: realItems.map((i) => i.json) } }];

const items = $input.all();
const realItems = items.filter((i) => i.json && Object.keys(i.json).length > 0);
if (realItems.length === 1) {
  const only = realItems[0].json;
  const looksLikeError = only && typeof only === 'object' && !Array.isArray(only) && (only.message || only.status) && !Array.isArray(only.alerts);
  if (looksLikeError) return [{ json: only }];
}
return [{ json: { alerts: realItems.map((i) => i.json) } }];

const input = $input.first().json;
const context = input.context || {};
const failedTests = context.failed_tests || [];

// Always emit >=1 item -- n8n skips a downstream node entirely on 0 input
// items, so a real "no failed tests" case (the common case) must not
// silently break the chain. The sentinel is routed around the Execute
// Workflow call by the IF node right after this.
if (failedTests.length === 0) {
  return [{ json: { _no_failed_tests: true } }];
}

return failedTests.map((t) => ({
  json: {
    test_name: (t.classname ? t.classname + '.' : '') + t.name,
    repo: context.repository || '',
    // Always 'main' -- deliberately NOT context.branch. get_test_history
// exists to compare against the STABLE branch's history; a PR run
// reports its OWN branch here, which has little/no history of its own.
// (Bug found live: using context.branch here caused a real flaky test
// to be wrongly re-derived as a regression, since the PR branch only
// had 1 run of its own history vs main's real 6-run flaky pattern.)
    branch: 'main',
  },
}));

// Independently re-verifies every flaky/regression classification the agent
// made. This does NOT trust the agent's own math: it re-calls get_test_history
// itself (upstream Execute Workflow node) and derives its own classification
// from the raw history -- if the two disagree, that's a real signal for the
// Gate. The agent cannot talk its way past a contradiction in the evidence.
//
// Two tiers of evidence, not blended:
//  - PROOF (same_sha_contradiction): the exact same commit produced both a
//    pass and a fail across different re-runs. Since the code did not change
//    between those runs, this is airtight -- it cannot be a code regression,
//    only environmental/non-deterministic flakiness. This is checked first.
//  - PATTERN (mixed_pattern): pass/fail mixed across DIFFERENT commits, with
//    no single contradicting SHA found. Suggestive of flakiness, not proof --
//    labeled explicitly as weaker so it's never presented as "definite."
const agentOutput = $('Parse Agent Output').first().json;
const agentFindings = (agentOutput.agent_parsed && agentOutput.agent_parsed.test_findings) || [];
const items = $input.all();

const isSentinel = items.length > 0 && items.every((i) => i.json._no_failed_tests === true);
let verifications = [];

function classifyFromHistory(result) {
  if (!result || result.runs_checked === 0 || (result.pass_count === 0 && result.fail_count === 0)) {
    return { cls: 'insufficient_evidence', proof: 'none' };
  }

  const bySha = {};
  for (const run of result.history || []) {
    if (!run.head_sha) continue;
    if (!bySha[run.head_sha]) bySha[run.head_sha] = new Set();
    bySha[run.head_sha].add(run.status);
  }
  const contradictingSha = Object.keys(bySha).find((sha) => bySha[sha].has('pass') && bySha[sha].has('fail'));
  if (contradictingSha) {
    return { cls: 'flaky', proof: 'same_sha_contradiction', sha: contradictingSha };
  }

  if (result.fail_count > 0 && result.pass_count > 0) {
    return { cls: 'flaky', proof: 'mixed_pattern' };
  }
  if (result.fail_count === 0 && result.pass_count > 0) {
    return { cls: 'regression', proof: 'no_prior_failures' };
  }
  return { cls: 'insufficient_evidence', proof: 'none' };
}


// --- TEST ATTRIBUTION (jury feedback) -----------------------------------
// "Why is a flaky test being reported on a README-only PR?" The honest answer
// has to come from the diff and from main's history, not from the model.
//
// Each reason below is independently sufficient and independently checkable;
// they are collected rather than short-circuited so the comment can show all
// of them. Absence of a reason is NOT proof the PR caused the failure, so the
// fallback label is 'possibly_introduced', never 'introduced'.
let scope = { available: false, reason_unavailable: 'scope lookup did not run' };
try {
  scope = $('Ensure PR Scope').first().json.pr_scope || scope;
} catch (e) {
  scope = { available: false, reason_unavailable: 'scope lookup did not run' };
}

function attributeTest(result, det) {
  const reasons = [];

  if (scope.available && !scope.touches_code) {
    reasons.push(`This PR changes no code files (only: ${(scope.changed_files || []).join(', ')}), so it cannot have altered test behaviour.`);
  }
  if ((result.fail_count || 0) > 0) {
    reasons.push(`This test already failed ${result.fail_count} time(s) on main, independently of this PR.`);
  }
  if (det.proof === 'same_sha_contradiction' && det.sha) {
    reasons.push(`Commit ${String(det.sha).slice(0, 10)} on main both passed and failed, so the test is non-deterministic regardless of this PR.`);
  }

  if (reasons.length > 0) return { attribution: 'pre_existing', attribution_reasons: reasons };
  if (!scope.available) {
    return { attribution: 'unknown', attribution_reasons: [`PR scope unavailable (${scope.reason_unavailable}) -- cannot attribute this failure.`] };
  }
  return {
    attribution: 'possibly_introduced',
    attribution_reasons: [`This PR changes code (${(scope.code_files || []).join(', ')}) and this test has no prior failures on main.`],
  };
}

function normalizeAgentClass(text) {
  const t = (text || '').toUpperCase();
  if (t.includes('FLAKY')) return 'flaky';
  if (t.includes('REGRESSION')) return 'regression';
  if (t.includes('INSUFFICIENT')) return 'insufficient_evidence';
  return 'unknown';
}

if (!isSentinel) {
  verifications = items.map((item) => {
    const result = item.json;
    // GLM has returned test_findings as an array of plain STRINGS as well as
    // an array of objects, for the same prompt. A string finding used to match
    // nothing, which silently dropped the entire deterministic cross-check from
    // the report -- our own headline evidence, lost to the model's formatting.
    const shortName = (result.test_name || '').split('.').pop();
    const agentFinding = agentFindings.find((f) => {
      if (typeof f === 'string') {
        if (!result.test_name) return false;
        return f.includes(result.test_name) || (shortName && f.includes(shortName));
      }
      const fName = f.test_name || f.name || f.test || '';
      if (!fName || !result.test_name) return false;
      return fName === result.test_name || fName.endsWith(result.test_name) || result.test_name.endsWith(fName);
    });
    const agentFindingText = typeof agentFinding === 'string'
      ? agentFinding
      : (agentFinding ? (agentFinding.classification || agentFinding.status || '') : '');
    const det = classifyFromHistory(result);
    const agentClass = agentFinding ? normalizeAgentClass(agentFindingText) : 'not_reported';
    const agrees = !agentFinding ? null : agentClass === det.cls;

    return {
      test_name: result.test_name,
      agent_claimed: agentFinding ? String(agentFindingText).slice(0, 300) : '(agent reported no finding for this test)',
      agent_class_normalized: agentClass,
      deterministic_class: det.cls,
      proof_type: det.proof,
      contradicting_sha: det.sha || null,
      deterministic_evidence: {
        runs_checked: result.runs_checked,
        pass_count: result.pass_count,
        fail_count: result.fail_count,
        unknown_count: result.unknown_count,
      },
      agrees,
      ...attributeTest(result, det),
    };
  });
}

return [{
  json: {
    ...agentOutput,
    flaky_verification: verifications,
  },
}];

// Builds a GitHub-flavored Markdown PR comment from the Gate's verdict.
// Different LLM providers name fields differently even given the same schema
// instructions (confirmed tonight: DeepSeek uses test_name/alert/classification,
// GLM uses name/dependency/status) -- every field read here tries multiple
// candidate names and falls back to a raw JSON dump rather than silently
// dropping a finding.
const gate = $('Deterministic Validation Gate').first().json;
const prLookupItems = $input.all().map((i) => i.json);
// Switched from commits/{sha}/pulls (that endpoint returned an empty result
// for this repo/PAT combo even for a same-repo open PR, confirmed via direct
// live testing) to listing open PRs and matching by head sha client-side --
// this endpoint is the one already proven reliable.
const prs = prLookupItems.filter(
  (p) => p && typeof p === 'object' && typeof p.number === 'number' && p.head && p.head.sha === gate.head_sha
);

if (prs.length === 0) {
  return [{ json: { _no_pr_found: true } }];
}

function pick(obj, keys, fallback) {
  for (const k of keys) {
    if (obj && obj[k] !== undefined && obj[k] !== null && obj[k] !== '') return obj[k];
  }
  return fallback;
}

function restAsText(obj, usedKeys) {
  const parts = [];
  for (const k of Object.keys(obj || {})) {
    if (usedKeys.includes(k)) continue;
    const v = obj[k];
    if (typeof v === 'string' && v.trim()) parts.push(v.trim());
  }
  return parts.join(' ');
}

function fmtTestFinding(f) {
  // string finding (fmtTestFinding): some models return findings as prose strings rather
  // than objects. Render them as readable text -- dumping JSON at a developer
  // is worse than no formatting at all.
  if (typeof f === 'string') return '- ' + f.trim() + '\n';
  const name = pick(f, ['test_name', 'name', 'test'], null);
  if (!name) {
    // Not a per-test finding at all -- e.g. GLM sometimes adds a suite-level
    // summary shaped like {test_suite, note} alongside real per-test entries.
    const note = pick(f, ['note', 'detail', 'evidence'], null);
    if (note) return '_' + note + '_\n';
    return '```json\n' + JSON.stringify(f) + '\n```\n';
  }
  const cls = pick(f, ['classification', 'status'], 'unclassified');
  let evidence = pick(f, ['evidence', 'detail', 'note'], '');
  const action = pick(f, ['action'], '');
  if (!evidence) evidence = restAsText(f, ['test_name', 'name', 'test', 'classification', 'status', 'action']);
  let out = '**`' + name + '`** — ' + cls + '\n';
  if (evidence) out += '> ' + String(evidence).replace(/\n/g, ' ') + '\n';
  if (action) out += '\nSuggested action: ' + action + '\n';
  return out;
}

function fmtSecurityFinding(f) {
  // string finding (fmtSecurityFinding): some models return findings as prose strings rather
  // than objects. Render them as readable text -- dumping JSON at a developer
  // is worse than no formatting at all.
  if (typeof f === 'string') return '- ' + f.trim() + '\n';
  const dep = pick(f, ['dependency', 'alert', 'package'], null);
  if (!dep) {
    // Summary-only item (e.g. GLM's omitted-alerts note) -- render as a note, not a card.
    const note = pick(f, ['note', 'detail', 'evidence', 'reachability'], null);
    if (note) return '_' + note + '_\n';
    return '```json\n' + JSON.stringify(f) + '\n```\n';
  }
  const ghsa = pick(f, ['ghsa', 'ghsa_id', 'cve'], '');
  const severity = pick(f, ['severity'], '');
  const status = pick(f, ['status', 'classification'], '');
  // GLM has used 'evidence', 'detail', AND 'reachability' for this same
  // purpose across different runs -- same model, inconsistent field naming.
  let evidence = pick(f, ['evidence', 'detail', 'reachability', 'note'], '');
  const caveat = pick(f, ['caveat'], '');
  if (!evidence) evidence = restAsText(f, ['dependency', 'alert', 'package', 'ghsa', 'ghsa_id', 'cve', 'severity', 'status', 'classification', 'caveat']);
  let header = '**' + dep + '**';
  if (ghsa) header += ' — `' + ghsa + '`';
  if (severity) header += ' (' + severity + ')';
  if (status) header += ' — ' + status;
  let out = header + '\n';
  if (evidence) out += '> ' + String(evidence).replace(/\n/g, ' ') + '\n';
  if (caveat) out += '\n_Caveat: ' + String(caveat).replace(/\n/g, ' ') + '_\n';
  return out;
}

const decision = (gate.final_decision || 'unknown').toUpperCase();
const flakyLines = (gate.flaky_verification || []).map((v) => {
  const verdict = v.agrees === null
    ? 'could not be compared to the agent (it reported no structured finding for this test), but stands on its own:'
    : (v.agrees ? 'agrees with the agent:' : '**disagrees with** the agent:');
  let proofLine;
  if (v.proof_type === 'same_sha_contradiction') {
    proofLine = 'PROVEN, not a pattern guess: commit `' + (v.contradicting_sha || '').slice(0, 10) +
      '` -- the exact same code -- passed on one run and failed on another re-run. Since nothing changed between those runs, this cannot be a code regression.';
  } else if (v.proof_type === 'mixed_pattern') {
    proofLine = 'Pattern-based, not proof: pass/fail mixed across different commits, with no single commit showing a contradicting result. Suggestive of flakiness, weaker than a same-commit contradiction.';
  } else if (v.proof_type === 'no_prior_failures') {
    proofLine = 'This test has no prior failures in the checked history -- a first-time failure is treated as a real regression, not flakiness.';
  } else {
    proofLine = 'Insufficient history to classify with confidence.';
  }
  const attrNote = (v.attribution_reasons || []).length
    ? '\n  - _Attribution: ' + v.attribution_reasons.join(' ') + '_'
    : '';
  return '- Independent re-verification of `' + v.test_name + '` (fresh `get_test_history` call, not the agent\'s own tool call) ' + verdict +
    ' re-derived as **' + v.deterministic_class + '** (' + v.deterministic_evidence.pass_count + ' pass / ' +
    v.deterministic_evidence.fail_count + ' fail across ' + v.deterministic_evidence.runs_checked + ' runs on main). ' + proofLine + attrNote;
}).filter(Boolean);

const overridesBlock = (gate.deterministic_overrides || []).length
  ? gate.deterministic_overrides.map((o) => '- ' + o).join('\n')
  : '_No deterministic overrides this run -- the agent\'s decision stood as evaluated._';

const semantic = gate.semantic || {};
const _ktSeen = new Set();
const knownTrackedList = (gate.known_tracked || []).filter((k) => {
  const key = String(k.ghsa || k.dependency || '').toUpperCase();
  if (!key || _ktSeen.has(key)) return false;
  _ktSeen.add(key);
  return true;
});
const testFindings = (gate.agent_test_findings || []).map(fmtTestFinding).join('\n');
const securityFindings = (gate.agent_security_findings || []).map(fmtSecurityFinding).join('\n');
const requiredActions = (gate.agent_required_actions || []).map((a, i) => (i + 1) + '. ' + a).join('\n');

let body = '## AutoRelease AI — Validation Report\n\n';
body += '### Decision: ' + decision + ' _(confidence: ' + gate.final_confidence + '%)_\n\n';
body += (gate.agent_summary || '') + '\n\n';
if (gate.html_url) body += '[View CI run](' + gate.html_url + ')\n\n';

const scope = gate.pr_scope || { available: false };
