  const semanticIntroduced = semantic.available ? (semantic.regression_candidate_count || 0) : 0;
  if (introducedAlerts.length + flakyMaybe.length + semanticIntroduced === 0) {
    const bits = [];
    if (preExistingAlerts.length) bits.push(preExistingAlerts.length + ' dependency finding(s)');
    if (flakyPre.length) bits.push(flakyPre.length + ' test failure(s)');
    body += '**Nothing in this report was introduced by this PR.**';
    if (bits.length) {
