body += '---\n\n';

if (testFindings) {
  body += '#### Test Findings\n\n' + testFindings + '\n';
}
if (flakyLines.length) {
  body += '**Deterministic flaky/regression cross-check** _(independently re-verified, not just LLM self-report)_\n\n' + flakyLines.join('\n') + '\n\n';
}
