  const sevCount = {};
  knownTrackedList.forEach((k) => { const s = String(k.severity || 'unknown').toLowerCase(); sevCount[s] = (sevCount[s] || 0) + 1; });
  const sevText = ['critical', 'high', 'medium', 'low', 'unknown'].filter((s) => sevCount[s]).map((s) => sevCount[s] + ' ' + s).join(', ');
  body += '#### Already tracked (skipped, not re-investigated)\n\n';
  body += '**' + knownTrackedList.length + '** known vulnerabilities (' + sevText + ') were found on earlier runs and are already open as issues, so the agent did not spend tool calls re-deriving them. They still count against release readiness.\n\n';
  body += '<details><summary>Show the ' + knownTrackedList.length + ' tracked issues</summary>\n\n';
