      json: {
        repository,
        title: `[AutoRelease AI] ${a.dependency || 'dependency'} ${a.ghsa}`,
        body: [
          `**Severity:** ${a.severity || 'unknown'}`,
          `**Package:** ${a.dependency || 'unknown'} (${a.ecosystem || 'unknown'}) in \`${a.manifest_path || 'unknown'}\``,
