const prs = items.filter((p) => p && typeof p === 'object' && typeof p.number === 'number' && p.head);
const match = prs.find((p) => p.head.sha === ctx.head_sha);

return [{
  json: {
    ...ctx,
    pr_number: match ? match.number : null,
    pr_title: match ? match.title : null,
    pr_html_url: match ? match.html_url : null,
    pr_base_ref: match ? match.base?.ref : null,
