const artifacts = (resp && resp.artifacts) || [];
const match = artifacts.find((a) => a.name === 'semantic-captures' && !a.expired);

return [{
  json: {
    ...ctx,
    semantic_artifact_id: match ? match.id : null,
    semantic_artifact_url: match ? match.archive_download_url : null,
    semantic_lookup_note: match
      ? null
